import pandas as pd,numpy as np
from pymatgen.core import Structure
T=pd.read_csv('cdft_piezo_d_train.csv');P=pd.read_csv('cdft_piezo_pool.csv')
sel=[]
for _,r in T.iterrows():
 if r.formula in ['RbPbBr3','TiPbO3','TlHgF3','TlCdF3','RbCaCl3','SrHfO3']:sel.append(('train',r.formula,r.d_ij,r.poscar))
for _,r in P.iterrows():
 if r.candidate_id in ['c025','c026','c041']:sel.append((r.candidate_id,r.formula,None,r.poscar))
for typ,f,d,p in sel:
 s=Structure.from_str(p,fmt='poscar');print('\n',typ,f,d,s.get_space_group_info(.1),'lat',s.lattice,'\nsites')
 for i,site in enumerate(s):
  ds=sorted([(site.distance(x),x.specie.symbol) for j,x in enumerate(s) if j!=i])
  # use get neighbors periodic
  ns=sorted([(x.nn_distance,x.specie.symbol) for x in s.get_neighbors(site,5)])[:12]
  print(i,site.specie, np.round(site.frac_coords,4),[(round(a,3),b) for a,b in ns[:8]])
